export const fourteenSlots = groupSizes.flatMap((size, group) => Array(size).fill(group));

export const fourteenReadings = [
  `သူလဆိုတာ တံကျင်လျှိုသလိုဖြစ်တာမျိုးကို ခေါ်တယ်။ လှံတံလို ထိပ်ဖျားချွန်ပြီး ထိုးသွင်းလက်နက်လို သုံးနိုင်တဲ့ အရာဝတ္ထုများကို ခေါ်တယ်။

ကျမ်းရင်း အဟော – ဇာတရှင် ဒီဌာနမှာ ရှိသူဟာ လက်နက်ကို စွန့်ခွာလိမ့်မယ်။ စည်းစိမ်ချမ်းသာကို စွန့်ခွာလိမ့်မယ်တဲ့။ ဆိုလိုတာက ရဏဆိုတဲ့ စစ်မှာ အရှုံးပေးမယ်ပေါ့လေ။ ပြီးတော့ မြင်အောင် ကြည့်ပါဦး။ လက်နက် ကိုင်ထားသူကသာ လက်နက်ကို စွန့်ဖို့ ဖြစ်လာတာပါ။ လက်နက်မကိုင်ထားသူဟာ လက်နက်စွန့်စရာ မရှိပါဘူး။

ဒါဖြင့် ... ဒီနက္ခတ် စန်းယှဉ်ချိန်မှာ စားသောက်ဆိုင်ဖွင့်ဖို့ အခါပေးတယ်။ ဒါဟာ ဆိုင်ရှင်က စီးပွားရေး စစ်မျက်နှာတစ်ခု ဖွင့်တာပါ။ ငါ့ဆိုင်ကို လာပြီး မင်းတို့ ပိုက်ဆံပေးကြကွာဆိုတဲ့ သဘောပေါ့။ အဲဒီမယ် ဆိုင်ရှင်ဟာ စားသောက်သူတွေရှေ့မှာ အရှုံးပေးသွားရပါလိမ့်မယ်။ ဒီစီးပွားရေး ဆက်မလုပ်တော့ပါဘူးဆိုတဲ့စိတ်တွေ ဖြစ်သွားပါလိမ့်မယ်။

သန့်ရှင်းတဲ့ အစားအစာလေး စားစေချင်တာ ဒါမှမဟုတ် ဒီလို ဝန်ဆောင်မှုလေး ရစေချင်တာ၊ ငါ တတ်နိုင်တာလေးပဲ လုပ်မယ်၊ မရောင်းရရင် လှူပစ်မယ်ဆိုတဲ့ စိတ်မျိုး ရှိသူကို ဒီနက္ခတ် စန်းယှဉ်ချိန်မှာ လုပ်ငန်းစဖို့ အခါပေးလိုက်ရင်တော့ အုန်းအုန်းထ အောင်မြင်ပါလိမ့်မယ်။ ဘာလို့လဲဆိုတော့ သူ့မှာ လက်နက်မပါလို့ပါ။ ငွေရှင်ဖြစ်တဲ့ စားသုံးသူတွေကသာ ဒီဆိုင်က အစားအစာတွေအတွက် ငါ ပိုက်ဆံပေးဖို့ တန်ရဲ့လား၊ ကောင်းရဲ့လား၊ မြည်းကြည့်ဦးမယ်ဆိုတဲ့ စိတ်နဲ့ လာကြတာ ဖြစ်တယ်။ ဒီတော့ ဒီလူတွေဟာ သူတို့ရဲ့ ငွေဆိုတဲ့ လက်နက် စွန့်သွားပြီး ဒီဆိုင်ရဲ့ ပင်တိုင် ဖောက်သည်တွေ ဖြစ်သွားကြတယ်ပေါ့။

အပေါ်က ဥပမာကို ပြန်ကောက်ပါဦးမယ်။ စီးပွားရေး စစ်မျက်နှာ ဖွင့်ထားတယ်ဆိုတဲ့ ဆိုင်ရှင်ကို ကျွန်တော်က ဘာအကြံပေးသလဲဆိုရင် ကြော်ငြာနေတာတွေ အားလုံးကို ရပ်ပစ်လိုက်ပါဆိုတဲ့ စကားတစ်ခွန်းပါပဲ။ ဘာလို့လဲဆိုတော့ ကြော်ငြာတာဟာ မိမိ ဖွင့်လှစ်ထားတဲ့ စစ်မျက်နှာအတိုင်း တိုက်ခိုက်နေတဲ့ သဘောဖြစ်လို့ပါ။ ကိုယ်က အရင် လက်နက်စွန့်လိုက်တဲ့ သဘောပါ။ လက်နက် မရှိသူဟာ လက်နက်စွန့်စရာ မလိုပါဘူး။

စဉ်းစားတွေးခေါ်ပုံ အင်မတန် နူးညံ့သိမ်မွေ့တာကို သတိထားမိကြသလား မသိ ... ။ ရဏဆိုတဲ့ စစ်ပွဲများအကြောင်းကို ရှေးဟောင်း အိန္ဒိယရဲ့ စဉ်းစားတွေးခေါ်ပုံ နောကျေနေသူတွေမှ ခုလို ကိစ္စတွေကို စဉ်းစားတွေးခေါ်နိုင်၊ အသုံးချနိုင်တာ ဖြစ်ပါတယ်။ ပြီးတော့ အခြေခံတွေကိုလဲ ကျေညက်နေပါလိမ့်မယ်။ ဥပမာ – ဒီနက္ခတ်ဟာ ဆိုင်ရှင်ရဲ့ ဝိနာသကနက္ခတ် ဖြစ်နေပြီး၊ ဆိုင်ဖွင့်တဲ့ တိထီတွေ၊ ရက်တွေအရ ဝိနာသယုဂ် ရနေရင် .... ။

နောက်တစ်ချက် မြင်အောင် ထောက်ပြပါဦးမယ်။ လက်နက်ကိုင်ပြီး တိုက်သူဟာ ယာယီပါ။ နဂိုက ဘယ်တော့မှ လက်နက် မကိုင်ပါဘူး။ ယာယီက လက်နက်နဲ့ ရောက်လာမှ နဂိုဟာ ဗျူဟာဆင်တာ ဖြစ်တယ်။ ဒါကြောင့် ဒီနက္ခတ် စန်းယှဉ်ချိန်မှာ လက်နက်ကိုင်လာတဲ့ ယာယီက လက်နက်စွန့်မယ်။ ဒီနက္ခတ်နဲ့ စန်းယှဉ်မွေးသူဟာ လက်နက်မကိုင်လို့ ဘယ်တော့မှ ယာယီ ဖြစ်မလာဘူး။ ဒီနက္ခတ် စန်းယှဉ်မွေးသူဟာ နဂိုဖြစ်နေရင် ငြိမ်းချမ်းရေးဆိုတဲ့ အမြင်ကို ဘယ်တော့မှ မစွန့်လွှတ်ရပါဘူး။ ငြိမ်းချမ်းရေးအမြင် မရှိပဲ မိမိကိုယ် မိမိ ခုခံကာကွယ်ဖို့ မဟုတ်ပဲ၊ အနိုင်ရလိုဇောနဲ့ လက်နက်ကိုင်မိရင် ဒီနဂိုဟာ လက်နက်စွန့်ရပါလိမ့်မယ်။

အပေါ်က စာပိုဒ်မှာ ဖတ်လိုက်ရတဲ့ နဂို၊ ယာယီတွေအကြောင်းဟာ ဖတ်ဖူး၊ ဖတ်စ မရှိသူများအတွက် နားလည်ဖို့ အင်မတန် ခက်မှာ သိပါတယ်။ အသေးစိတ်ကို ဆဋ္ဌင်္ဂရာဟု ကာလာနလစက်မှာ ဖတ်ကြရပါလိမ့်မယ်။ ဒီတော့ ခုနေ နားမလည်သေးရင် ထားခဲ့ပါ။ ပြဿနာ မရှိပါဘူး။

ဒီနဂို ယာယီ အတွေးအခေါ်ဟာလဲ ရှေးဟောင်း အိန္ဒိယရဲ့ တီထွင်မှု အစစ်ပါ။ ဒါကြောင့် အိန္ဒိယ ယဉ်ကျေးမှု နောက်ခံကနေ လာထားတဲ့ ပညာခွင်မှာ မြန်မာမူ သရောဒယစစ်စစ်ပါလို့ ဟန်ဆောင်ပြီး အော်ချင်ရင် အင်မတိ အင်မတန် ဉာဏ်ကြီးကြရပါလိမ့်မယ်။ ဥပမာ တစ်ခု ပြပါမယ်။ နာဠာဂိရိဆင်ဟာ လက်နက်နဲ့ လာသူ ဖြစ်ပြီး ဘုရားရှင်ဟာ ဘာလက်နက်မှ ဆောင်ထားတော် မမူပါဘူး။ အင်္ဂုလိမာလဟာ လက်နက်နဲ့ လာသူဖြစ်ပြီး ဘုရားရှင်ဟာ အင်္ဂုလိမာလရဲ့ မေးခွန်းတွေကို ဖြေရှင်းကာနေမှ သစ္စာတရားကို သိမြင်အောင် ဆောင်ရွက်သွား ဖြစ်တယ်။ ဟုတ်ကဲ့ ... ဘုရားရှင်ဟာ မွေးလရဲ့ လပြည့်နက္ခတ်ကနေ စပြီး ချတဲ့ စက်မှာ ဇာတနက္ခတ် ဒီဌာနမှာ ရှိနေတာ ဖြစ်တယ်။ ဒါကြောင့် မဟာ ကရုဏာတော်ရှင်ဟာ လက်နက် မဆောင် အောင်ခြင်းကြီး အောင်တော်မူသူ ဖြစ်ပါတယ်။`,
  `ကျမ်းရင်းရဲ့ အဟောက တိုတိုလေးပါပဲ။ အောင်မြင်ပါလိမ့်မယ်တဲ့။ ဒါပေမယ့် ဒီဌာနက နက္ခတ်တွေဟာ အင်မတန် ပရိယာယ် မာယာများပါတယ်။ ဒီတော့ အများကြီး ပြောစရာ ရှိပါသေးတယ်။

ကီလနဲ့ ပတ်သက်လာရင် စီးပွားရေးကဏ္ဍမှာ ဟောဒီ အချက်တွေကို ယေဘုယျအားဖြင့် ထည့်သွင်း စဉ်းစားရပါမယ်။

– အရင်းအနှီး ထည့်ဝင်ခြင်း။
– အလုပ်/ရာထူး/တာဝန်/နေရာ။
– အလုပ်/ရာထူး/တာဝန်/နေရာ ပေးအပ်ခံရခြင်း။
– မရမက ဖက်တွယ်ထားခြင်း။
– ငုတ်ရိုက်ပြီး ပိုင်နက်ကန့်သတ်သော သဘော။
– အပိုင်စားယူခြင်း။
– အလစ်မပေးပဲ ချောင်းမြောင်းထောက်လှမ်းခြင်း။

ဒီနက္ခတ်ဟာ ပါပဂြိုဟ်အစရှိတာတွေကြောင့် နာနေရင် စီးပွားရေးကဏ္ဍမှာ ဟောဒီ အချက်တွေကို ထည့်သွင်း စဉ်းစားရပါမယ်။

– မခန့်မှန်းနိုင်အောင် ရုတ်တရက် ပြောင်းလဲတတ်သော သဘော။
– လောင်းကြေးထပ်ခြင်း။
– ချိန်ခွင်လျှာပေါ်တွင် ရှိနေခြင်း (အတိမ်းအစောင်း မခံခြင်း)။
– မရမက ဖက်တွယ်ထားမှု ခံနေရခြင်း။
– ငုတ်ရိုက်ပြီး ပိုင်နက်ကန့်သတ်မှု ခံရသော သဘော။
– အပိုင်စားယူခံရခြင်း။
– အလစ်မပေးပဲ ချောင်းမြောင်းထောက်လှမ်းခံရခြင်း။

ကီလရဲ့ ယေဘုယျသဘောတွေကို ခု ဆက်ပြီး ရေးပြပါမယ်။ ဒါတွေကို လူမှုရေး၊ စိတ်ခံစားချက်၊ အတွေးအမြင်၊ စဉ်းစားတွေးခေါ်ပုံ အစရှိတာတွေမှာ သူ့နေရာနဲ့သူ ထည့်သွင်း စဉ်းစားတတ်ပါစေ။

– အိမ်ရိုက်သံကဲ့သို့ သံချောင်းမျိုး။
– ကန့်လန့်ဖြစ်သော သဘော။
– စို့။
– သပ်။
– ငုတ်။
– တံကျင်။
– မွေးအံ့ဆဲဆဲ၊ မွေးနေဆဲ ကလေး။
– တံခါးမင်းတုံး။ တံခါးမင်းတုံး၏ သဘော။
– တူရွင်း။ တူရွင်း၏ သဘော။
– တွယ်အပ်၊ တွယ်ချိတ်။ တွယ်အပ်၊ တွယ်ချိတ်၏ သဘော။
– ပစ္စည်းချိတ်သော ချိတ်။
– ကင်းဆာကျိတ်ကဲ့သို့သော အကျိတ်အခဲ၏ သဘော။
– အထိန်းအချုပ်၏ သဘော။
– ရှေးခေတ်က လူကို မီးရှို့သတ်ချိန်တွင် လူကို ချည်သောတိုင်။

ကီလအတွက် ယတြာ အစီအရင်တွေမှာ ဒါတွေကို သုံးရပါတယ်။

– လက်နက်။
– မီး။ (ထင်း၊ မီးသွေးကဲ့သို့ လောင်စာ/ဖယောင်းတိုင်/မီးခြစ်)
– တိုင်။
– နွားချည်တိုင်။
– ဖြည်းညင်းစွာ တောက်လောင်နေသော မီးတောက်ငယ်။ (မငြိမ်းဆီမီး။)
– အသား
– (မည်သည့်ပစ္စည်းမဆို) အလွန် သေးငယ်သော အမှုန်များ။ (ဥပမာ–ဆား။)

ရှေ့မှာ ပြောခဲ့တာတွေထဲကနေ သင့်လျော်သလိုလဲ ယူပါ။ ဥပမာ – အိမ်ရိုက်သံ၊ သွပ်ရိုက်သံတွေ လှူလို့ ရတယ်။ တံခါးမင်းတုံး လှူလို့ ရတယ်။ တူရွင်း လှူလို့လဲ ရပါတယ်။ ဉာဏ်နဲ့ ချိန်ဆ ရွေးချယ်ပါ။

တွက်ရတာ ခက်တယ်။ ယူဆရတာ ပိုခက်တယ်။ ဒါတွေကို ကျွန်တော် မငြင်းပါဘူး။ ဒါပေမယ့် တွက်ချက်၊ ယူဆ၊ ချိန်ဆပြီးတဲ့ နောက်မှာ ပေးလိုက်တဲ့ ယတြာ အစီအရင်ဟာ လှည့်ကြည့်စရာ မလိုအောင် ကောင်းလွန်းလှပါတယ်။ သရောဒယပညာဟာ ဒီလို အစီအရင်တွေကြောင့် ထီးသုံးနန်းသုံးပညာအဖြစ် ကျော်ကြားတာပါ။

ကီလမှာ ရေးပေးထားတဲ့ ဒီ အချက်လေးတွေကို ကျွန်တော်က သုံးနှစ်ကျော် ရှာဖွေ စုဆောင်းခဲ့ရပါတယ်။ အလွယ်ပြောရရင် – ဘယ်တုန်းကလဲဆိုတာလဲ မမှတ်မိပါဘူး။ ဘာအတွက်ဆိုတာလဲ မမှတ်မိတော့ပါဘူး။ ဆရာနဲ့ ကျွန်တော် ယတြာတစ်ခုကို ချိန်ဆရင်းနဲ့ နွားချည်တိုင် လိုအပ်တယ်ဆိုပြီး သက်ဆိုင်ရာ နက္ခတ်ရဲ့ အပင်က အသားနဲ့ နွားချည်တိုင် လုပ်ခိုင်းထားပြီးမှ အဲဒီ နွားချည်တိုင်နဲ့ ယတြာဆင်ဖူးပါတယ်။ ဒီဆရာ တပည့် အတော် လက်ညီကြတာပါ။`,
  `သူ့အဟောကလဲ တိုတိုလေးပါ။ ရန်သူ့စခန်းအတွင်းသို့ မဆုတ်မယုတ်ရပဲ ဖောက်ထွင်း ဝင်ရောက်နိုင်ပါမယ်တဲ့။ အဲသလို ဝင်နိုင်ဖို့ လွယ်တာမှ မဟုတ်တာ။ ဒီတော့ ဇာတာရှင်ဟာ အင်မတန်မှ ဉာဏ်ရည်ဉာဏ်သွေး ကောင်းတာ၊ အဝင်အထွက်၊ အတက်အဆုတ်သဘောတွေကို နားလည်တာမျိုးတွေပေါ့။ ပရိယာယ် သဘော၊ မာယာ၊ ဗျူဟာတွေရဲ့ သဘောကို နားလည်တတ်ကျွမ်းတာမျိုးပေါ့။

နျူနဆိုတာက သေးဖွဲသော၊ မပြောပလောက်သော ပမာဏကို ခေါ်ပါတယ်။ ဒီတော့ စီးပွားရေးဆိုင်ရာ အကျိုးအမြတ်တွေအတွက်ဆိုရင် .... ။`,
  `အဟောကတော့ – မှားယွင်းစေတတ်ပါတယ်။ အလှည့်အပြား ခံရတတ်ပါတယ်။ မတိဆိုတာ စိတ်နေစိတ်ထား၊ စိတ်ခံစားချက်ကို ပြောတာပါ။`,
  `အထူးသဖြင့် အောင်မြင်ခြင်း။`,
  `အဟောက – နှောင့်ယှက်ခံရမယ်။ ထွက်ပြေးရမယ်။

ဒီနေရာမှာ ကုလဆိုတဲ့ စကားလုံးရဲ့ သဘောက – စစ်ရဲ့ နောက်ကျောပိုင်း။ ဆင်ခြေလျှော။ မြစ်ကမ်း။ တောင်ကုန်း။ ရေအိုင်။`,
  `အလွန် ရက်စက်ကြမ်းကြုတ်မယ်။`,
  `ပါဏိဟာ မူလမှာဆိုရင်တော့ အလွန်ကောင်းပါတယ်။ တစ်သက်လုံး ဘယ်သူ သတ်လို့မှ မသေတော့ပါဘူး။ ဒီနက္ခတ် သုံးလုံးရဲ့ သဘောဟာ – လက်။ ချေး။ လက်ကုန်ထုတ်ပြီး လောင်းရတဲ့ သဘော။

အာဓာနနက္ခတ်ဟာ ယာဉ်ရထားကိုလဲ ဟောပါတယ်။ ကျွန်တော့် အသိတစ်ယောက်ဟာ ငွေနည်းနည်းကျပ်နေပေမယ့် ကားစီးချင်တော့ ဘဏ်ကနေ အရစ်ကျ ရောင်းပေးတဲ့ ကားကို သူ့ရဲ့ အာဓာနနက္ခတ် ဟောဒီ ပါဏိနေရာကို ရောက်နေချိန်မှာ လက်မှတ်ထိုးပြီး ယူလိုက်ပါတယ်။ ဟုတ်ကဲ့ .... အရစ်ကျငွေ မသွင်းနိုင်တော့လို့ ဘဏ်က ကားကို သိမ်းသွားပါတယ်။`,
  `ဒီနက္ခတ် နှစ်လုံးဟာ အရည်ပျော်တဲ့ သဘောကို ပြောပါတယ်။ ရေကြောင့် ဘေးသင့်တဲ့ သဘောကိုလဲ ပြောပါတယ်။`,
  `ဥပဂြဟအစရှိတာတွေမှာ ဥက္ကာလသဘောတွေ ရေးထားပါတယ်။ သဘောတရား အတူတူပါပဲ။`,
  `ဝိနာသကနက္ခတ်သဘောကို ရေးခဲ့ဖူးပါပြီ။ အဲဒီကနေ ယူကြပါ။ အတူတူပါပဲ။`,
  `အဟောက – ပျက်စီးပါတယ်တဲ့။ ဝကြဆိုတာ နောက်ပြန်ဆုတ်တဲ့ သဘောကို ပြောချင်တာပါ။ ဒါကြောင့် နောက်ဆုတ်တတ်ရင် ရှင်မယ်။ နောက်မဆုတ်တတ်ရင် သေမယ်။ ဝကြဟာ ကောက်ကျစ်တဲ့ သဘောကိုလဲ ဆိုလိုပါတယ်။`,
  `အဟောက – ညှဉ်းပန်းတတ်ပါတယ်။ အညှဉ်းပန်း ခံရတတ်ပါတယ်။ ဟနုကဆိုတာ မေးရိုးကို ခေါ်ပါတယ်။`,
  `ပျက်စီးတတ်ပါတယ်။ ပျက်စီးခြင်းခံရတတ်ပါတယ်။`
];

export const fourteenNote = `ဒီစက်ကို ဘယ်နည်းနဲ့ပဲ တွက်ပြီးချသည်ဖြစ်စေ – ဟနုကနဲ့ ဒွံသနနေရာမှာ ဇာတနက္ခတ် ရှိနေချိန်မှာ – ‘ကောင်းသော အရပ်တွင် ကောင်းသော အစီအရင်ကို ပြုသည်ရှိသော် နှစ်ဆတက် အောင်မြင်မှုကို ပေးတတ်၏’ လို့ ကျမ်းမှာ ရေးပါတယ်။ လုပ်ကြည့်ပါ။ အလွန်ကောင်းတာ သိရပါလိမ့်မယ်။ ဒီနှစ်နေရာက ဇာတနက္ခတ်ကို ပါပဂြိုဟ် ထွင်းထားရင် ဇာတာရှင် စိတ်ထား ပြောင်းလဲဖောက်ပြန်ပါလိမ့်မယ်။ ဇာတနက္ခတ် မဟုတ်ပဲ အာဓာနက္ခတ်၊ ကမ္မနက္ခတ်စသည်ဖြင့် အခြားနက္ခတ်တွေဆိုရင်လဲ အဲဒီနက္ခတ်တွေက ဖော်ညွှန်းတဲ့ နယ်ပယ်တွေမှာ ဇာတာရှင်ဟာ စိတ်ထားတွေ ပြောင်းလဲမှာပေါ့ဗျာ။`;
